1	/**
2	 * Generate the CSS API reference from the shipped component/utility stylesheets.
3	 *
4	 * The rendering (pages, index, sidebar, escaping, structure diagrams, token tables) lives in
5	 * `@cssdoc/markdown` and is driven here through `@cssdoc/typedoc`'s `emitCssApi` — the same plugin the
6	 * rest of the ecosystem uses, dogfooded before it's published. All that stays pantoken-specific is the
7	 * token resolution: `resolveToken` cross-references the `--instui-*` IR (type + light/dark value) and
8	 * `resolveSource` links each record to its source. `emitCssApi` writes `docs/api/css/**` and merges a
9	 * "CSS" section into the TypeDoc sidebar, so the CSS pages ride along in the same nav. The in-page live
10	 * `@example` previews are seamed on at compile time by `demoMarkdownIt` (see `.vitepress/config.ts`),
11	 * not here — the generated `.md` stays a plain source fence.
12	 *
13	 * Runs after `docs:api:en` (TypeDoc cleans `docs/api` and writes `typedoc-sidebar.json`, which this
14	 * merges into) and before `docs:api:locales`/vitepress.
15	 */
16	import { readFileSync, readdirSync, writeFileSync } from "node:fs";
17	import { join, relative } from "node:path";
18	import { CssDocConfigFile } from "@cssdoc/config";
19	import { emitCssApi } from "@cssdoc/typedoc";
20	import { parseCssDocs, type CssDocEntry } from "@cssdoc/core";
21	import { tokens, type Token } from "@pantoken/tokens";
22	import { makeResolver, unknownReferences } from "@pantoken/utils";
23	import { BADGE_CLASS_BY_LABEL } from "./api-badge-classes.ts";
24	
25	const docsRoot = join(import.meta.dirname, "..");
26	
27	const CSS_OVERVIEW_BLURB =
28	  "The CSS API reference covers pantoken's class-based component layer: components, utilities, " +
29	  "global rules, and declarations built on the token system.";
30	
31	const tokenByName = new Map(tokens.map((t) => [t.name, t]));
32	
33	// Resolve a token value to its concrete form: expand every `var(...)` down to primitives, keeping a
34	// `light-dark(a, b)` pair intact (no `mode`), so a themed value shows both its light and dark result.
35	// Rebuilt in build() once the sheet-local custom properties are indexed, so `var(--pantoken-*)`
36	// references (e.g. the toggle geometry `calc()`s) resolve too.
37	let resolveValue = makeResolver(tokens);
38	
39	/**
40	 * Custom properties defined in the sheets themselves (not the token IR) — the `--instui-elevation-*`
41	 * shadows and `--instui-focus-outline-*` ring — so their values can be resolved too. Populated by
42	 * {@link build} before rendering.
43	 */
44	const localVars = new Map<string, string>();
45	
46	/**
47	 * Infer a CSS `@property` syntax from a resolved token value. Component/semantic tokens carry `syntax:
48	 * "*"` (they're contextual `var()` aliases or `light-dark()` pairs that can't be a static `@property`
49	 * type), so the human-meaningful type is derived from what the value ultimately IS.
50	 */
51	function inferSyntax(value: string): string | undefined {
52	  const v = value.trim();
53	  // A bare url()/data: value (the icon glyphs are url-encoded SVGs) is `<url>`, not the broader `<image>`.
54	  if (/^url\(|data:/iu.test(v)) return "<url>";
55	  // Themed values are colours in this system; so are hex / rgb / hsl / oklch / lab / color().
56	  if (
57	    /light-dark\s*\(/iu.test(v) ||
58	    /(#[0-9a-f]{3,8}\b|\b(?:rgb|hsl|hwb|oklch|oklab|lab|lch|color)\()/iu.test(v)
59	  )
60	    return "<color>";
61	  if (/-?\d*\.?\d+(?:px|rem|em|vh|vw|vmin|vmax|svh|svw|ch|ex|cm|mm|in|pt|pc|q|%)\b/iu.test(v))
62	    return "<length>";
63	  if (/^-?\d*\.?\d+m?s$/iu.test(v)) return "<time>";
64	  if (/^-?\d+$/u.test(v)) return "<integer>";
65	  if (/^-?\d*\.?\d+$/u.test(v)) return "<number>";
66	  return undefined;
67	}
68	
69	/**
70	 * Composite / keyword-valued properties can't be inferred from a single value (`solid` alone doesn't
71	 * imply the set; a box-shadow or font stack isn't a primitive), but the token name says which property
72	 * it feeds — so map it to that property's CSS value-definition grammar (CSS Values 4 §2.1 notation:
73	 * `|` `||` `&&` `[]` `?` `{a,b}` `#`). Matched by name substring, most-specific first, so it also catches
74	 * variants (`…-text-decoration-outside-text`) and non-IR tokens (elevation shadows, the focus ring).
75	 */
76	const LINE_STYLE =
77	  "none | hidden | dotted | dashed | solid | double | groove | ridge | inset | outset";
78	const PROPERTY_SYNTAX: [RegExp, string][] = [
79	  [/font-family/u, "[ <font-family-name> | <generic-font-family> ]#"],
80	  [/elevation/u, "[ inset? && <length>{2,4} && <color>? ]# | none"],
81	  [/text-decoration/u, "none | underline || overline || line-through || blink"],
82	  [/focus-outline-color/u, "<color> | invert"],
83	  [/focus-outline-style/u, `auto | ${LINE_STYLE}`],
84	  [/focus-outline-(width|offset|radius)/u, "<length>"],
85	  [/border-style/u, LINE_STYLE],
86	  // Icon glyph vars hold a url-encoded SVG; type by name so even the value-less placeholder resolves.
87	  [/glyph/u, "<url>"],
88	  [/-filter\b/u, "<filter-value-list> | none"],
89	];
90	
91	/**
92	 * The human-meaningful syntax of a consumed token: the first concrete `syntax` along its `refersTo`
93	 * chain, else inferred from the terminal value, else the enumerated keyword set for keyword-valued
94	 * properties. Returns undefined only when nothing can be derived.
95	 */
96	function resolveSyntax(name: string): string | undefined {
97	  const seen = new Set<string>();
98	  let token = tokenByName.get(name);
99	  while (token) {
100	    if (token.syntax && token.syntax !== "*") return token.syntax;
101	    if (token.refersTo && !seen.has(token.refersTo)) {
102	      seen.add(token.refersTo);
103	      token = tokenByName.get(token.refersTo);
104	      continue;
105	    }
106	    const inferred = token.value ? inferSyntax(token.value) : undefined;
107	    if (inferred) return inferred;
108	    break;
109	  }
110	  // Composite/keyword property grammar by name (font-family, box-shadow, glyph, …) takes precedence
111	  // over primitive inference; then fall back to inferring from a sheet-local value.
112	  const prop = PROPERTY_SYNTAX.find(([re]) => re.test(name))?.[1];
113	  if (prop) return prop;
114	  const local = localVars.get(name);
115	  return local ? inferSyntax(resolveValue(local)) : undefined;
116	}
117	
118	/**
119	 * The `resolveToken` hook `@cssdoc/markdown` calls for each consumed `--instui-*` property: its
120	 * human-meaningful type ({@link resolveSyntax}) and its concrete value (IR value, else a sheet-local
121	 * var), resolved down to primitives. Undefined when neither can be derived.
122	 */
123	function resolveToken(name: string): { syntax?: string; value?: string } | undefined {
124	  const syntax = resolveSyntax(name);
125	  const raw = tokenByName.get(name)?.value ?? localVars.get(name);
126	  const value = raw ? resolveValue(raw) : undefined;
127	  return syntax || value ? { syntax, value } : undefined;
128	}
129	
130	// Use the generated CSS files (which retain doc comments) instead of the packaged dist (which tsdown/css
131	// strips comments from). This ensures `parseCssDocs` can extract `@component`, `@utility` records.
132	const generatedCssDir = join(docsRoot, "..", "formats", "components", "generated");
133	const cssPath = (subpath: string): string => join(generatedCssDir, subpath);
134	const readCss = (subpath: string): string => readFileSync(cssPath(subpath), "utf8");
135	
136	/**
137	 * `classNames` (new in `@cssdoc/markdown` 0.7.2) lets HTML-preserving renderers wrap the deprecation
138	 * marker — the record-level `> [!WARNING]` banner and every deprecated modifier-table cell — in a
139	 * `<span class="…">`. We render it as an `instui-pill` in the warning colour (components.css is already
140	 * loaded on doc pages for the live examples, so the class paints). The extra `pantoken-doc-tag` is a
141	 * docs-only marker: the shipped pill is a compact fixed-height badge, so `.vitepress/theme/pantoken.css`
142	 * uses it to relax the pill for the flowing deprecation sentence it wraps — without touching how the
143	 * real `.instui-pill` renders in a component preview. Keep the deprecated class in sync with the
144	 * TypeDoc badge transformer via `api-badge-classes.ts`.
145	 */
146	const classNames = {
147	  deprecated: BADGE_CLASS_BY_LABEL.Deprecated,
148	};
149	
150	// The repo root (this worktree) and its GitHub blob base, for `**Source:**` links.
151	const repoRoot = join(docsRoot, "..");
152	const SOURCE_URL_BASE = "https://github.com/thedannywahl/pantoken/blob/main";
153	
154	/** Map each record name → its authoring source file (repo-relative), by scanning for the record tag. */
155	function sourceMap(files: string[]): Map<string, string> {
156	  const RECORD = /@(?:component|utility|rule|declaration)\s+([a-z][\w-]*)/u;
157	  const map = new Map<string, string>();
158	  for (const file of files) {
159	    const m = readFileSync(file, "utf8").match(RECORD);
160	    if (m && !map.has(m[1])) map.set(m[1], relative(repoRoot, file));
161	  }
162	  return map;
163	}
164	
165	/** A `resolveSource` hook: link a record to its source file (GitHub blob), labelled with the filename. */
166	const makeResolveSource =
167	  (map: Map<string, string>) =>
168	  (entry: CssDocEntry): { href: string; label?: string } | undefined => {
169	    const path = map.get(entry.name);
170	    return path ? { href: `${SOURCE_URL_BASE}/${path}`, label: path.split("/").pop() } : undefined;
171	  };
172	
173	/**
174	 * Every authoring source under `<componentsRoot>/src/{components,utilities,rules,declarations}` + the
175	 * color record's generate.ts. Scans both `.css` (the migrated static records carry the `@component` tag
176	 * in their co-located `.css`) and `.ts` (the parametric records — button, the input controls, heading —
177	 * still author the tag inside a `css` template). A migrated record's `.ts` is a tag-less wrapper, so
178	 * `sourceMap` skips it and links to the `.css`.
179	 */
180	function componentSources(componentsRoot: string): string[] {
181	  const files = ["components", "utilities", "rules", "declarations"].flatMap((d) => {
182	    const dir = join(componentsRoot, "src", d);
183	    return readdirSync(dir)
184	      .filter((f) => f.endsWith(".ts") || f.endsWith(".css"))
185	      .map((f) => join(dir, f));
186	  });
187	  files.push(join(componentsRoot, "scripts", "generate.ts")); // the `color` utility's doc lives here
188	  return files;
189	}
190	
191	const build = (): void => {
192	  // The component sheet is the primary source; base/utilities/prose carry the non-component records
193	  // (@rule/@utility/@declaration). All four feed the emitter so every record is picked up in one pass.
194	  const sheets = ["components.css", "utilities.css", "prose.css", "base.css"];
195	  const cssPaths = sheets.map(cssPath);
196	  const css = sheets.map(readCss).join("\n");
197	
198	  // The CSS-emitting plugins (stacking/transition/visual-debug/logos/primitives) carry cssdoc records in
199	  // their generated sheets, each tagged `@group Plugins` so cssdoc folds them into a "Plugins" subsection
200	  // of the CSS section (it groups by `@group`, falling back to record kind). They render in the SAME pass
201	  // as the component records — one `emitCssApi` call, one "CSS" section.
202	  const PLUGIN_RECORDS = [
203	    {
204	      pkg: "plugins/pantoken/stacking",
205	      sheet: "stacking.css",
206	      import: "@pantoken/plugin-stacking/stacking.css",
207	    },
208	    {
209	      pkg: "plugins/pantoken/transition",
210	      sheet: "transition.css",
211	      import: "@pantoken/plugin-transition/transition.css",
212	    },
213	    {
214	      pkg: "plugins/pantoken/visual-debug",
215	      sheet: "visual-debug.css",
216	      import: "@pantoken/plugin-visual-debug/visual-debug.css",
217	    },
218	    {
219	      pkg: "plugins/pantoken/logos",
220	      sheet: "logos.css",
221	      import: "@pantoken/plugin-logos/logos.css",
222	    },
223	    {
224	      pkg: "plugins/pantoken/primitives",
225	      sheet: "primitives.css",
226	      import: "@pantoken/plugin-primitives/primitives.css",
227	    },
228	  ];
229	  const pluginSheet = (r: (typeof PLUGIN_RECORDS)[number]): string =>
230	    join(repoRoot, r.pkg, "generated", r.sheet);
231	  const pluginPaths = PLUGIN_RECORDS.map(pluginSheet);
232	
233	  // Index every sheet-local custom property so its value resolves like an IR token — elevation shadows +
234	  // focus ring in the component sheets, `--instui-stacking-*`/`--instui-transition-*` in the plugin
235	  // sheets; first definition wins. Rebuild the resolver with them in scope.
236	  for (const text of [css, readCss("base.css"), ...pluginPaths.map((p) => readFileSync(p, "utf8"))])
237	    for (const m of text.matchAll(/(--[\w-]+)\s*:\s*([^;{}]+);/gu))
238	      if (!localVars.has(m[1])) localVars.set(m[1], m[2].trim());
239	  const localTokens: Token[] = [...localVars].map(([name, value]) => ({
240	    name,
241	    value,
242	    syntax: "*",
243	    inherits: true,
244	  }));
245	  resolveValue = makeResolver([...tokens, ...localTokens]);
246	
247	  // Load the repo's shared cssdoc.json (root) — the single declarative config that also drives the lint
248	  // plugins and the per-record test guard. `configFile` feeds `emitCssApi` (parse config + `render`
249	  // order/heading); `configuration` is its parse view, reused locally for `parseCssDocs`.
250	  const componentsRoot = join(generatedCssDir, "..");
251	  const configFile = CssDocConfigFile.loadForFolder(repoRoot);
252	  const configuration = configFile.toConfiguration();
253	
254	  // `**Source:**` link → each record's authoring source: a component `.ts`/`.css`, or a plugin's
255	  // `scripts/generate.ts` (where its doc block is authored). Record names don't collide, so one map.
256	  const pluginSources = PLUGIN_RECORDS.map((r) => join(repoRoot, r.pkg, "scripts", "generate.ts"));
257	  const resolveSource = makeResolveSource(
258	    sourceMap([...componentSources(componentsRoot), ...pluginSources]),
259	  );
260	
261	  // `## Usage` import → the record's sheet: `@pantoken/components/<sheet>` (+ the per-component subpath),
262	  // or the plugin's static `./<name>.css` subpath export.
263	  const recordSheet = new Map<string, string>();
264	  for (const sheet of sheets)
265	    for (const e of parseCssDocs(readCss(sheet), { configuration })) recordSheet.set(e.name, sheet);
266	  const pluginImportByName = new Map<string, string>();
267	  for (const r of PLUGIN_RECORDS)
268	    for (const e of parseCssDocs(readFileSync(pluginSheet(r), "utf8"), { configuration }))
269	      pluginImportByName.set(e.name, r.import);
270	  const importSnippet = (entry: CssDocEntry): string | undefined => {
271	    const pluginImport = pluginImportByName.get(entry.name);
272	    if (pluginImport) return `@import "${pluginImport}";`;
273	    const sheet = recordSheet.get(entry.name);
274	    if (!sheet) return undefined;
275	    if (entry.kind === "component") {
276	      return [
277	        `@import "@pantoken/components/${sheet}";`,
278	        `@import "@pantoken/components/${entry.name}.css";`,
279	      ].join("\n");
280	    }
281	    return `@import "@pantoken/components/${sheet}";`;
282	  };
283	
284	  const outSubdir = "css";
285	  const { entries, sidebarMerged } = emitCssApi({
286	    outputDirectory: join(docsRoot, "api"),
287	    css: [...cssPaths, ...pluginPaths],
288	    outSubdir,
289	    label: "CSS",
290	    baseHref: "/api/css/",
291	    // The four record kinds first, then the plugins' `@group Plugins` subsection last.
292	    groups: ["Components", "Utilities", "Rules", "Declarations", "Plugins"],
293	    configFile,
294	    classNames,
295	    resolveToken,
296	    resolveSource,
297	    importSnippet,
298	  });
299	
300	  // Add a short landing-page blurb to mirror the API overview style while keeping cssdoc-generated
301	  // tables and section ordering intact.
302	  const cssIndexPath = join(docsRoot, "api", outSubdir, "index.md");
303	  const cssIndex = readFileSync(cssIndexPath, "utf8");
304	  if (!cssIndex.includes(CSS_OVERVIEW_BLURB)) {
305	    const heading = "# CSS API reference\n\n";
306	    const withBlurb = cssIndex.startsWith(heading)
307	      ? `${heading}${CSS_OVERVIEW_BLURB}\n\n${cssIndex.slice(heading.length)}`
308	      : `# CSS API reference\n\n${CSS_OVERVIEW_BLURB}\n\n${cssIndex}`;
309	    writeFileSync(cssIndexPath, withBlurb);
310	  }
311	
312	  // `@cssdoc/markdown` keeps `@example` as a plain code fence (generic — it can't assume the host loads
313	  // the component CSS). Our docs do, so `demoMarkdownIt` seams a live preview onto each fence at compile
314	  // time (see `.vitepress/config.ts`); the generated `.md` here stays a plain source fence.
315	
316	  // Drift guard: every consumed token must exist in the IR (a typo'd var() is a build failure).
317	  const missing = unknownReferences(css, tokens).filter(
318	    (r) => !r.startsWith("--instui-elevation-") && !r.startsWith("--instui-focus-outline-"),
319	  );
320	  if (missing.length) {
321	    throw new Error(`CSS API: ${missing.length} unknown token reference(s): ${missing.join(", ")}`);
322	  }
323	
324	  console.log(
325	    `✓ CSS API: wrote ${entries.length} record page(s) to api/css/` +
326	      `${sidebarMerged ? " + merged the CSS section into the TypeDoc sidebar" : ""}`,
327	  );
328	};
329	
330	build();
331

